  function defaultState(){return {version:VERSION,unlocked:1,completed:{},best:{},knowledge:{},profilesSeen:{},lastStage:1,updatedAt:Date.now()};}
  function loadState(){try{var s=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(!s||s.version!==VERSION)return defaultState();s.completed=s.completed||{};s.best=s.best||{};s.knowledge=s.knowledge||{};s.profilesSeen=s.profilesSeen||{};s.unlocked=clamp(Number(s.unlocked)||1,1,STAGE_COUNT);return s;}catch(e){return defaultState();}}
  var state=loadState();
  function saveState(){state.updatedAt=Date.now();try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(e){}updateLauncher();}
  function resetState(){if(!window.confirm('Bindemitteltrainer wirklich zurücksetzen?\n\nNur der Fortschritt dieses Trainers wird gelöscht. Die normalen Lernkarten, Quizdaten und Prüfungen bleiben erhalten.'))return;state=defaultState();saveState();renderHome();}
  function stat(profile,aspect){var p=state.knowledge[profile]||(state.knowledge[profile]={}),s=p[aspect]||(p[aspect]={r:0,w:0});return s;}
  function mastery(profile,aspect){var s=stat(profile,aspect);return (s.r+1)/(s.r+s.w+2);}
  function updateKnowledge(item,ok){(item.profiles||[]).forEach(function(pid){var s=stat(pid,item.aspect||'basis');if(ok)s.r++;else s.w++;});saveState();}
  function weakLabel(){var worst=null;PROFILES.forEach(function(p){var k=state.knowledge[p.id];if(!k)return;var r=0,w=0;Object.keys(k).forEach(function(a){r+=Number(k[a].r)||0;w+=Number(k[a].w)||0;});if(r+w<2)return;var sc=(r+1)/(r+w+2);if(!worst||sc<worst.sc)worst={name:p.name,sc:sc};});return worst?worst.name:'Noch offen';}
  function completedCount(){return Object.keys(state.completed).filter(function(k){return state.completed[k];}).length;}
  function allMastery(){var r=0,w=0;Object.keys(state.knowledge).forEach(function(pid){Object.keys(state.knowledge[pid]||{}).forEach(function(a){r+=Number(state.knowledge[pid][a].r)||0;w+=Number(state.knowledge[pid][a].w)||0;});});return r+w?Math.round(100*r/(r+w)):0;}

